    description: "Caption",
  },
  roundLength: {
    type: "number",
    default: 20,
    min: 12,
    max: 40,
    step: 1,
    description: "Round length (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
