const ELEMENT_PROP_KEYS = new Set(["theme","title","caption","roundLength","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Champion",
  caption: "Playoffs 2026 · 8 teams · 0 maps dropped",
  roundLength: 20,
  accent: "#3B5BFD",
  fontFamily: "Tektur",
  scale: 1,
  delay: 0,
  speed: 1,
};

type BracketWinElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BracketWinBase>;

const BracketWinInner = forwardRef<
  HTMLDivElement,
  BracketWinElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BracketWin>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BracketWinBase
          {...(componentProps as unknown as ComponentProps<typeof BracketWinBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BracketWin = Interactive.withSchema({
  Component: BracketWinInner,
  componentName: "<BracketWin>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
